mapper.select:
;WITH VM AS ( SELECT DC_CD, MIN(VENDOR_CD) AS VENDOR_CD FROM TBL_VENDOR_MST WHERE ACTION_YN = 'Y' AND ISNULL(DC_CD,'') <> '' AND COMP_CD = #{compCd} GROUP BY DC_CD ) SELECT z.src AS src, z.custCd AS custCd, z.dt AS dt, z.docKey AS docKey, z.docNo AS docNo, z.itemCd AS itemCd, z.itemNm AS itemNm, z.spec AS spec, z.qty AS qty, z.price AS price, z.amt AS amt, z.supplyAmt AS supplyAmt, z.vatAmt AS vatAmt, z.taxGb AS taxGb FROM ( -- ① 정산서 SELECT 'STMT' AS src, vm.VENDOR_CD AS custCd, x.dt AS dt, 'STMT|' + x.dt AS docKey, LTRIM(RTRIM(ISNULL(s.ORD_NO,''))) + CASE WHEN ISNULL(s.ORD_ITEM_NO,'') <> '' THEN '-' + LTRIM(RTRIM(s.ORD_ITEM_NO)) ELSE '' END AS docNo, ISNULL(s.ITEM_CD,'') AS itemCd, ISNULL(s.ITEM_NM,'') AS itemNm, ISNULL(s.SPEC,'') AS spec, CAST(ISNULL(s.OUT_QTY,0) AS DECIMAL(18,2)) AS qty, CAST(ISNULL(s.SALE_PRICE,0) AS DECIMAL(18,2)) AS price, CAST(ISNULL(s.SALE_AMT,0) AS DECIMAL(18,0)) AS amt, CAST(NULL AS DECIMAL(18,0)) AS supplyAmt, CAST(NULL AS DECIMAL(18,0)) AS vatAmt, N'과세' AS taxGb FROM TBL_SALES_MST s CROSS APPLY ( SELECT ISNULL(NULLIF(s.DLV_DT,''), s.OUT_DT) AS dt, AS dcKey ) x JOIN VM vm ON vm.DC_CD = x.dcKey WHERE s.ACTION_YN = 'Y' AND s.COMP_CD = #{compCd} AND x.dt >= #{frDt} AND x.dt <= #{toDt}
UNION ALL -- ①-1 토더 발주 (「발주가 곧 매출」 — 일계장과 같은 금액식) SELECT 'TD', vm.VENDOR_CD, o.DLV_DT, 'TD|' + o.DLV_DT, LTRIM(RTRIM(ISNULL(o.ORD_NO,''))) + CASE WHEN ISNULL(o.ORD_ITEM_NO,'') <> '' THEN '-' + LTRIM(RTRIM(o.ORD_ITEM_NO)) ELSE '' END, ISNULL(o.ITEM_CD,''), ISNULL(o.ITEM_NM,''), '', CAST(q.qty AS DECIMAL(18,2)), CAST(ISNULL(o.SALE_PRICE,0) AS DECIMAL(18,2)), CAST(CASE WHEN ISNULL(o.DS_TRX_GB,'') = N'반품' THEN -1 ELSE 1 END * (q.qty * ISNULL(o.SALE_PRICE,0) - ISNULL(o.DS_DC_AMT,0)) AS DECIMAL(18,0)), CAST(NULL AS DECIMAL(18,0)), CAST(NULL AS DECIMAL(18,0)), N'과세' FROM TBL_SHIPOUT_MST o CROSS APPLY ( SELECT CASE WHEN ABS(o.CUR_QTY) > ABS(o.LABEL_QTY) THEN o.CUR_QTY ELSE ISNULL(o.LABEL_QTY, ISNULL(o.CUR_QTY,0)) END AS qty ) q JOIN VM vm ON vm.DC_CD = o.DC_CD WHERE o.ACTION_YN = 'Y' AND o.PROD_KIND = 'TD' AND o.COMP_CD = #{compCd} AND o.DLV_DT >= #{frDt} AND o.DLV_DT <= #{toDt}
UNION ALL -- ② 판매전표 명세 (공급가·세액이 전표에 있다) SELECT 'STRX', t2.CUST_CD, x2.dt, 'STRX|' + CAST(t2.SALE_SEQ AS VARCHAR(20)), ISNULL(t2.SALE_DT,'') + '-' + ISNULL(t2.SALE_NO,''), ISNULL(d2.PROD_CD,''), ISNULL(d2.PROD_NM, N'(명세 없음)'), ISNULL(d2.SPEC,''), CAST(ISNULL(d2.QTY,0) AS DECIMAL(18,2)), CAST(ISNULL(d2.UNIT_PRICE,0) AS DECIMAL(18,2)), CAST(ISNULL(d2.TOT_AMT, t2.TOT_AMT) AS DECIMAL(18,0)), CAST(CASE WHEN d2.SALE_SEQ IS NULL THEN ISNULL(t2.TOT_AMT,0) - ISNULL(t2.VAT_AMT,0) ELSE ISNULL(d2.SUPPLY_AMT,0) END AS DECIMAL(18,0)), CAST(CASE WHEN d2.SALE_SEQ IS NULL THEN ISNULL(t2.VAT_AMT,0) ELSE ISNULL(d2.VAT_AMT,0) END AS DECIMAL(18,0)), CASE WHEN ISNULL(t2.TAX_GB,'') = N'면세' THEN N'면세' ELSE N'과세' END FROM TBL_SALES_TRX_MST t2 CROSS APPLY ( SELECT ISNULL(NULLIF(t2.DLV_DT,''), t2.SALE_DT) AS dt ) x2 LEFT JOIN TBL_SALES_TRX_DTL d2 ON d2.SALE_SEQ = t2.SALE_SEQ AND d2.ACTION_YN = 'Y' AND d2.COMP_CD = t2.COMP_CD WHERE t2.ACTION_YN = 'Y' AND t2.COMP_CD = #{compCd} AND x2.dt >= #{frDt} AND x2.dt <= #{toDt}
UNION ALL -- ②-1 판매전표 머리 할인 (장부에서 매출을 깎는 값 — 일계장 saleDcAmt) SELECT 'STRXDC', t2.CUST_CD, x2.dt, 'STRX|' + CAST(t2.SALE_SEQ AS VARCHAR(20)), ISNULL(t2.SALE_DT,'') + '-' + ISNULL(t2.SALE_NO,''), '', N'할인', '', CAST(0 AS DECIMAL(18,2)), CAST(0 AS DECIMAL(18,2)), CAST(-ISNULL(t2.DC_AMT,0) AS DECIMAL(18,0)), CAST(NULL AS DECIMAL(18,0)), CAST(NULL AS DECIMAL(18,0)), CASE WHEN ISNULL(t2.TAX_GB,'') = N'면세' THEN N'면세' ELSE N'과세' END FROM TBL_SALES_TRX_MST t2 CROSS APPLY ( SELECT ISNULL(NULLIF(t2.DLV_DT,''), t2.SALE_DT) AS dt ) x2 WHERE t2.ACTION_YN = 'Y' AND t2.COMP_CD = #{compCd} AND ISNULL(t2.DC_AMT,0) <> 0 AND x2.dt >= #{frDt} AND x2.dt <= #{toDt}
UNION ALL -- ③ 수금전표의 매출할인(수금할인) — 「매출합계에서 수금할인액 제외」를 켰을 때만 화면이 쓴다 SELECT 'RCVDC', t.CUST_CD, t.TRX_DT, 'RCV|' + ISNULL(t.TRX_DT,'') + '-' + ISNULL(t.TRX_NO,''), ISNULL(t.TRX_DT,'') + '-' + ISNULL(t.TRX_NO,''), '', N'수금할인', '', CAST(0 AS DECIMAL(18,2)), CAST(0 AS DECIMAL(18,2)), CAST(-ISNULL(t.SALE_DC_AMT,0) AS DECIMAL(18,0)), CAST(NULL AS DECIMAL(18,0)), CAST(NULL AS DECIMAL(18,0)), N'과세' FROM TBL_SETTLE_TRX t WHERE t.ACTION_YN = 'Y' AND t.COMP_CD = #{compCd} AND t.TRX_GB = 'RCV' AND ISNULL(t.SALE_DC_AMT,0) <> 0 AND t.TRX_DT >= #{frDt} AND t.TRX_DT <= #{toDt}
UNION ALL -- ④ 수금 (수금기준) — 수금전표 + 판매전표 즉시수금 SELECT 'CASH', t.CUST_CD, t.TRX_DT, 'RCV|' + ISNULL(t.TRX_DT,'') + '-' + ISNULL(t.TRX_NO,''), ISNULL(t.TRX_DT,'') + '-' + ISNULL(t.TRX_NO,''), '', ISNULL(NULLIF(t.PAY_GB,''), N'수금'), '', CAST(0 AS DECIMAL(18,2)), CAST(0 AS DECIMAL(18,2)), CAST(ISNULL(t.AMT,0) AS DECIMAL(18,0)), CAST(NULL AS DECIMAL(18,0)), CAST(NULL AS DECIMAL(18,0)), N'과세' FROM TBL_SETTLE_TRX t WHERE t.ACTION_YN = 'Y' AND t.COMP_CD = #{compCd} AND t.TRX_GB = 'RCV' AND ISNULL(t.AMT,0) <> 0 AND t.TRX_DT >= #{frDt} AND t.TRX_DT <= #{toDt} UNION ALL SELECT 'CASH', t2.CUST_CD, x2.dt, 'STRX|' + CAST(t2.SALE_SEQ AS VARCHAR(20)), ISNULL(t2.SALE_DT,'') + '-' + ISNULL(t2.SALE_NO,''), '', N'즉시수금', '', CAST(0 AS DECIMAL(18,2)), CAST(0 AS DECIMAL(18,2)), CAST(ISNULL(t2.PAY_AMT,0) AS DECIMAL(18,0)), CAST(NULL AS DECIMAL(18,0)), CAST(NULL AS DECIMAL(18,0)), N'과세' FROM TBL_SALES_TRX_MST t2 CROSS APPLY ( SELECT ISNULL(NULLIF(t2.DLV_DT,''), t2.SALE_DT) AS dt ) x2 WHERE t2.ACTION_YN = 'Y' AND t2.COMP_CD = #{compCd} AND ISNULL(t2.PAY_AMT,0) <> 0 AND x2.dt >= #{frDt} AND x2.dt <= #{toDt} ) z WHERE ISNULL(z.custCd,'') <> '' ORDER BY z.custCd, z.dt, z.docKey, z.itemCd

SELECT z.src AS src, z.custCd AS custCd, z.dt AS dt, z.docKey AS docKey, z.docNo AS docNo, z.itemCd AS itemCd, z.itemNm AS itemNm, z.spec AS spec, z.qty AS qty, z.price AS price, z.amt AS amt, z.supplyAmt AS supplyAmt, z.vatAmt AS vatAmt, z.taxGb AS taxGb FROM ( SELECT 'PURCH' AS src, m.VENDOR_CD AS custCd, m.PURCH_DT AS dt, 'PURCH|' + CAST(m.PURCH_SEQ AS VARCHAR(20)) AS docKey, ISNULL(m.PURCH_DT,'') + '-' + ISNULL(m.PURCH_NO,'') AS docNo, ISNULL(d.PROD_CD,'') AS itemCd, ISNULL(d.PROD_NM, N'(명세 없음)') AS itemNm, ISNULL(d.SPEC,'') AS spec, CAST(ISNULL(d.QTY,0) AS DECIMAL(18,2)) AS qty, CAST(ISNULL(d.UNIT_PRICE,0) AS DECIMAL(18,2)) AS price, CAST(ISNULL(d.TOT_AMT, m.TOT_AMT) AS DECIMAL(18,0)) AS amt, CAST(CASE WHEN d.PURCH_SEQ IS NULL THEN ISNULL(m.TOT_AMT,0) - ISNULL(m.VAT_AMT,0) ELSE ISNULL(d.SUPPLY_AMT,0) END AS DECIMAL(18,0)) AS supplyAmt, CAST(CASE WHEN d.PURCH_SEQ IS NULL THEN ISNULL(m.VAT_AMT,0) ELSE ISNULL(d.VAT_AMT,0) END AS DECIMAL(18,0)) AS vatAmt, N'과세' AS taxGb FROM TBL_PURCHASE_MST m LEFT JOIN TBL_PURCHASE_DTL d ON d.PURCH_SEQ = m.PURCH_SEQ AND d.ACTION_YN = 'Y' AND d.COMP_CD = m.COMP_CD WHERE m.ACTION_YN = 'Y' AND m.COMP_CD = #{compCd} AND m.PURCH_DT >= #{frDt} AND m.PURCH_DT <= #{toDt}
UNION ALL SELECT 'PURCHDC', m.VENDOR_CD, m.PURCH_DT, 'PURCH|' + CAST(m.PURCH_SEQ AS VARCHAR(20)), ISNULL(m.PURCH_DT,'') + '-' + ISNULL(m.PURCH_NO,''), '', N'할인', '', CAST(0 AS DECIMAL(18,2)), CAST(0 AS DECIMAL(18,2)), CAST(-ISNULL(m.DC_AMT,0) AS DECIMAL(18,0)), CAST(NULL AS DECIMAL(18,0)), CAST(NULL AS DECIMAL(18,0)), N'과세' FROM TBL_PURCHASE_MST m WHERE m.ACTION_YN = 'Y' AND m.COMP_CD = #{compCd} AND ISNULL(m.DC_AMT,0) <> 0 AND m.PURCH_DT >= #{frDt} AND m.PURCH_DT <= #{toDt}
UNION ALL SELECT 'PAYDC', t.CUST_CD, t.TRX_DT, 'PAY|' + ISNULL(t.TRX_DT,'') + '-' + ISNULL(t.TRX_NO,''), ISNULL(t.TRX_DT,'') + '-' + ISNULL(t.TRX_NO,''), '', N'지급할인', '', CAST(0 AS DECIMAL(18,2)), CAST(0 AS DECIMAL(18,2)), CAST(-ISNULL(t.DC_AMT,0) AS DECIMAL(18,0)), CAST(NULL AS DECIMAL(18,0)), CAST(NULL AS DECIMAL(18,0)), N'과세' FROM TBL_SETTLE_TRX t WHERE t.ACTION_YN = 'Y' AND t.COMP_CD = #{compCd} AND t.TRX_GB = 'PAY' AND ISNULL(t.DC_AMT,0) <> 0 AND t.TRX_DT >= #{frDt} AND t.TRX_DT <= #{toDt}
UNION ALL SELECT 'CASH', t.CUST_CD, t.TRX_DT, 'PAY|' + ISNULL(t.TRX_DT,'') + '-' + ISNULL(t.TRX_NO,''), ISNULL(t.TRX_DT,'') + '-' + ISNULL(t.TRX_NO,''), '', ISNULL(NULLIF(t.PAY_GB,''), N'지급'), '', CAST(0 AS DECIMAL(18,2)), CAST(0 AS DECIMAL(18,2)), CAST(ISNULL(t.AMT,0) AS DECIMAL(18,0)), CAST(NULL AS DECIMAL(18,0)), CAST(NULL AS DECIMAL(18,0)), N'과세' FROM TBL_SETTLE_TRX t WHERE t.ACTION_YN = 'Y' AND t.COMP_CD = #{compCd} AND t.TRX_GB = 'PAY' AND ISNULL(t.AMT,0) <> 0 AND t.TRX_DT >= #{frDt} AND t.TRX_DT <= #{toDt} UNION ALL SELECT 'CASH', m.VENDOR_CD, m.PURCH_DT, 'PURCH|' + CAST(m.PURCH_SEQ AS VARCHAR(20)), ISNULL(m.PURCH_DT,'') + '-' + ISNULL(m.PURCH_NO,''), '', N'즉시지급', '', CAST(0 AS DECIMAL(18,2)), CAST(0 AS DECIMAL(18,2)), CAST(ISNULL(m.PAY_AMT,0) AS DECIMAL(18,0)), CAST(NULL AS DECIMAL(18,0)), CAST(NULL AS DECIMAL(18,0)), N'과세' FROM TBL_PURCHASE_MST m WHERE m.ACTION_YN = 'Y' AND m.COMP_CD = #{compCd} AND ISNULL(m.PAY_AMT,0) <> 0 AND m.PURCH_DT >= #{frDt} AND m.PURCH_DT <= #{toDt} ) z WHERE ISNULL(z.custCd,'') <> '' ORDER BY z.custCd, z.dt, z.docKey, z.itemCd

SELECT d.LINE_NO AS lineNo, ISNULL(d.ITEM_DT,'') AS itemDt, ISNULL(d.ITEM_CD,'') AS itemCd, ISNULL(d.ITEM_NM,'') AS itemNm,
       ISNULL(d.SPEC,'') AS spec, d.QTY AS qty, d.PRICE AS price, d.SUPPLY_AMT AS supplyAmt, d.VAT_AMT AS vatAmt, ISNULL(d.REMARK,'') AS remark
  FROM TBL_TAXBILL_DTL d
  JOIN TBL_TAXBILL_MST m ON m.BILL_SEQ = d.BILL_SEQ AND m.COMP_CD = #{compCd}
 WHERE d.BILL_SEQ = #{billSeq}
 ORDER BY d.LINE_NO
